"""Generate engine/src/wfhtml/html5_entities.rs from Python's html.entities.html5.

`wfhtml.to_plain_text` salvages malformed values with `html.unescape`, which uses the
full HTML5 named character reference table; the Rust port embeds the same table.
Run from the repository root:

    uv run python -I engine/tests/fixtures/wfhtml/gen_entities.py > engine/src/wfhtml/html5_entities.rs
"""

import sys
from html.entities import html5


def lit(s: str) -> str:
    out = []
    for c in s:
        if c.isascii() and (c.isalnum() or c in ";"):
            out.append(c)
        else:
            out.append(f"\\u{{{ord(c):x}}}")
    return '"' + "".join(out) + '"'


print("// @generated by engine/tests/fixtures/wfhtml/gen_entities.py from Python")
print(f"// {sys.version.split()[0]} html.entities.html5. Do not edit by hand.")
print()
print("/// HTML5 named character references (`name` without the `&`, possibly ending in")
print("/// `;`), sorted by name for binary search.")
print("pub(super) const HTML5: &[(&str, &str)] = &[")
for k in sorted(html5):
    print(f"    ({lit(k)}, {lit(html5[k])}),")
print("];")
